use vstd::prelude::*;

verus! {

fn ones(n: usize) -> (result: Vec<i8>)
    ensures
        result.len() == n,
        forall(|i: usize| (i < n) ==> result.index(i) == 1),
        forall(|i: usize, j: usize| (i < n && j < n) ==> result.index(i) == result.index(j)),
        forall(|i: usize| (i < n) ==> result.index(i) > 0)
{
    let mut res: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            i <= n,
            res.len() == i,
            // all elements currently in res are 1
            forall(|k: usize| (k < i) ==> res.index(k) == 1),
            forall(|k: usize, l: usize| (k < i && l < i) ==> res.index(k) == res.index(l)),
            forall(|k: usize| (k < i) ==> res.index(k) > 0),
        decreases n - i,
    {
        res.push(1);
        i = i + 1;
    }
    res
}

}
